  "paper": {
    "contribution": "Evaluates where exactly-once behavior should be enforced (model, harness, or tool contract) using Limbo, a deterministic sandbox with twelve boundary fault modes across 25,930 episodes.",
    "key_claims": [
      {
        "claim": "Frontier models instructed to act exactly once almost never duplicate a write whose acknowledgment was lost (0.5%), whereas weaker models duplicate in 18%.",
        "evidence": [
          {
            "page": 2,
            "section": "1",
            "quote": "Frontier models instructed to act exactly once almost never duplicate a write whose acknowledgement was lost (0.5% of episodes), because they verify before retrying; weaker models duplicate in 18%, and without the explicit instruction the weaker and faster models duplicate markedly more while the strongest are unaffected."
          }
        ]
      },
      {
        "claim": "Transparent client-side retries cut exactly-once success from 72% to 50% in the native contract, but with keys on every write, exactly-once success reaches 99%.",
        "evidence": [
          {
            "page": 2,
            "section": "1",
            "quote": "Transparent client-side retries cut exactly-once success from 72% to 50%. In the native contract even an outcome oracle that sees in-flight requests reaches only 87%, because redelivery on key-less writes is beyond any client-side policy; with keys on every write and a guard that attaches them, the duplicate rate of a shared model is at most 0% even without the guard, and exactly-once success is at least 100% with it."
          }
        ]
      },
      {
        "claim": "In 90% of episodes that produced a duplicate side effect, agents reported the task as completed.",
        "evidence": [
          {
            "page": 2,
            "section": "1",
            "quote": "Agents do not know when they have duplicated. In 90% of episodes that produced a duplicate, the agent reported the task as completed."
          }
        ]
      }
    ],
    "limitations": [
      {
        "page": 16,
        "section": "Limitations",
        "quote": "The services are simulated, although their semantics follow documented production conventions and every fault fires at the service boundary rather than in the prompt."
      },
      {
        "page": 16,
        "section": "Limitations",
        "quote": "All models were reached through one gateway, which fixes some settings (for example reasoning effort) at provider defaults, and model identifiers refer to versions available in September 2026."
      },
      {
        "page": 16,
        "section": "Limitations",
        "quote": "Our tasks are short to medium in length; long-horizon workflows compound the effects we measure but also introduce failure modes we do not study."
      },
      {
        "page": 16,
        "section": "Limitations",
        "quote": "gpt-4.1 is served from a separate low quota and its E1 coverage is incomplete (87%); it is reported per model but excluded from pooled statistics."
      }
    ]
  },
